(async function(){await PolishedSprites.ready;const N=NeonCombat,B=PoolBoss193,c=document.querySelector('canvas'),ctx=c.getContext('2d');let g,playing=false;function reset(){g=new N.Brawler();g.selectHero(document.querySelector('#hero').value);Casino192.start(g,2);g.pending=[];g.reinforce=()=>{};g.player.x=1550;g.player.y=475;g.player.inv=0;g.player.hp=g.player.maxHp=1000;g.finishFinancialTick(.02);g.camera=1040;g.ai=()=>{};for(const[e,i]of B.pair(g).map((e,i)=>[e,i])){e.x=1670+i*170;e.y=475;e.cd=0;}draw();}function draw(){CasinoView192.scene(ctx,g);for(const e of[g.player,...g.enemies].filter(e=>!e.poolState193).sort((a,b)=>a.y-b.y)){ctx.save();ctx.translate(e.x-g.camera,e.y-(e.grappleZ||0));ctx.scale(e.dir*N.Forest125.scale(e),N.Forest125.scale(e));PolishedSprites.draw(ctx,e,g.time);ctx.restore();}CasinoView192.foreground(ctx,g);document.querySelector('pre').textContent=JSON.stringify({phase:g.poolFight193.phase,time:g.time.toFixed(2),player:{hp:g.player.hp,held:!!g.player.heldBy,down:g.player.down},bosses:B.pair(g).map(e=>({name:e.name,hp:e.hp,move:e.act?.kind193,frame:Math.round((e.act?.t||0)*60),rage:!!e.enraged193,pool:e.poolState193?.phase,waterSeconds:e.poolState193?.t.toFixed(2),waterX:e.poolState193?.x.toFixed(1),returnX:e.poolState193?.returnX.toFixed(1)}))},null,2);}function step(n=1){for(let i=0;i<n;i++)g.tick(1/60,{});draw();}document.querySelector('#reset').onclick=reset;document.querySelector('#step').onclick=()=>step();document.querySelector('#second').onclick=()=>step(60);document.querySelector('#play').onclick=()=>playing=!playing;document.querySelector('#waiting').onclick=()=>{reset();g.poolFight193.phase='waiting';for(const e of B.pair(g)){e.dormant=true;e.x=e.poolBoss193==='ophelia'?1800:1884;e.y=465;}draw();};document.querySelector('#pool').onclick=()=>{for(const e of B.pair(g))B.inPool(g,e);draw();};for(const[id,seconds]of[['swim194',11],['climb194',13.2],['return194',14.2]])document.getElementById(id).onclick=()=>{reset();for(const e of B.pair(g))B.inPool(g,e);step(Math.round(seconds*60));};document.querySelector('#rage').onclick=()=>{B.pair(g)[0].hp=0;g.finishFinancialTick(.01);draw();};for(const k of Object.keys(B.moves)){const b=document.createElement('button');b.textContent=k;b.onclick=()=>{reset();const e=B.pair(g)[['front','spin','fly','jump','kicks','grab'].includes(k)?1:0];e.x=1500;e.y=475;g.player.x=k==='fly'?1740:k==='jump'?1650:1550;if(k==='stomp'){g.knockDown(g.player,1,3,true);g.player.fallFrom=g.player.fallTo=g.player.x;g.player.downAge=.5;g.player.landed=true;}B.attack(g,e,k);draw();};document.querySelector('#moves').append(b);}reset();let last=0;function loop(t){if(playing&&t-last>16){step();last=t;}requestAnimationFrame(loop);}requestAnimationFrame(loop);})();
